//! ASH publisher topic pages and implementation links; journal articles are independent terminals.
use super::{common,Adapter,PlanRow};
use super::pmc_crosswalk::{self as cw,Lookup,SourceRef};
use super::r2b_crosswalk::{self as xw,Citation,Cross};
use crate::guidelines::{doc::{GuidelineDoc,Rights},fetch::Fetcher,html::{blocks_from_html,sel,text_of},registry::SourceEntry};
use anyhow::{bail,Context,Result};use scraper::Html;use serde_json::json;use std::collections::{HashSet,VecDeque};use url::Url;
pub struct AshHematology;
const ROOT:&str="https://www.hematology.org/resources/clinical-practice-guidelines";
fn page(raw:&str,base:&Url)->Result<(String,String,Vec<String>,Vec<serde_json::Value>)>{let d=Html::parse_document(raw);let root=d.select(&sel("main")).next().context("ASH main source root missing")?;let title=root.select(&sel("h1")).next().map(|x|text_of(&x)).context("ASH topic title missing")?;if title.is_empty(){bail!("ASH title empty")};let mut children=vec![];let mut seen=HashSet::new();for a in root.select(&sel("section[data-component='SectionListingDefault'] a[href], section[data-component='QuickLinks'] a[href]")){if let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h)){let u=Url::parse(&url)?;if u.host_str()==Some("www.hematology.org")&&u.path().to_lowercase().starts_with("/resources/clinical-practice-guidelines/")&&seen.insert(url.to_lowercase()){children.push(url)}}}let mut assets=vec![];for a in root.select(&sel("section[data-component='AlertBanner'] a[href], section[data-component='MediaDownloadDefault'] a[href]")){let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h))else{continue};let label=text_of(&a);let pu=Url::parse(&url)?;let role=if pu.host_str()==Some("ashpublications.org")||(pu.host_str()==Some("doi.org")&&pu.path().starts_with("/10.1182/")){"publisher_article_terminal"}else if label.to_lowercase().contains("slide"){"teaching_slides"}else if label.to_lowercase().contains("overview")||label.to_lowercase().contains("full vte guidelines"){"guideline_overview"}else{"implementation_resource"};assets.push(json!({"url":url,"label":label,"role":role,"rights":"unknown"}));}for a in root.select(&sel("section[data-component='PageHeader'] a[href]")){let label=text_of(&a);let role=match label.as_str(){"View the Full Guidelines"=>"publisher_article_terminal","Download an Overview of the Guidelines"=>"guideline_overview",_=>continue};let Some(url)=a.value().attr("href").and_then(|h|common::link(base,h))else{continue};if !assets.iter().any(|x|x["url"]==url){assets.push(json!({"url":url,"label":label,"role":role,"rights":"unknown"}));}}for a in assets.iter_mut(){if a["role"]=="publisher_article_terminal"{let(doi,loc)=article_identity(a["url"].as_str().unwrap_or(""));a["doi"]=json!(doi);a["citation_locator"]=loc;}}Ok((title,root.html(),children,assets))}
/// Identifier stated by the ASH link itself: a DOI (doi.org/… or …/article/doi/10.…/…) or, for volume/issue/page
/// links, that printed citation locator. Nothing is looked up or guessed here.
fn article_identity(url:&str)->(Option<String>,serde_json::Value){let Ok(u)=Url::parse(url) else {return (None,serde_json::Value::Null)};let segs:Vec<&str>=u.path_segments().map(|s|s.filter(|x|!x.is_empty()).collect()).unwrap_or_default();
 if u.host_str()==Some("doi.org"){let d=u.path().trim_start_matches('/');if d.starts_with("10."){return (Some(d.to_string()),serde_json::Value::Null)}}
 if u.host_str().is_some_and(|h|h.ends_with("ashpublications.org")){if let Some(i)=segs.iter().position(|x|*x=="doi"){let parts:Vec<&str>=segs[i+1..].iter().take_while(|x|!x.chars().all(|c|c.is_ascii_digit())).copied().collect();if parts.len()>=2&&parts[0].starts_with("10."){return (Some(parts.join("/")),serde_json::Value::Null)}}
  if segs.len()>=5&&segs[1]=="article"&&segs[2..5].iter().all(|x|x.chars().all(|c|c.is_ascii_digit())){return (None,json!({"journal":segs[0],"volume":segs[2],"issue":segs[3],"first_page":segs[4]}))}}
 (None,serde_json::Value::Null)}
/// Journal ISSNs for the citation-only ASH links (print ISSN as Europe PMC indexes it).
fn ash_issn(journal:&str)->Option<&'static str>{match journal{"bloodadvances"=>Some("2473-9529"),"blood"=>Some("0006-4971"),_=>None}}
/// PMC crosswalk for one ASH article link: the DOI the link states, else its printed volume/issue/first page resolved
/// through Europe PMC (unique match only). Returns the full-text row (if any) and the outcome.
async fn crosswalk(s:&SourceEntry,f:&Fetcher,cx:&mut xw::Session,a:&serde_json::Value,target:&str,landing:&str,source_doc:String)->(Option<PlanRow>,Cross){
 let fail=|status:&'static str,reason:String|(None,Cross{row:None,relation:None,status,evidence:json!({"status":status,"reason":reason,"url":target}),reason:Some(reason)});
 let (lookup,route,resolution)=if let Some(d)=a["doi"].as_str().and_then(|d|cw::normalize_doi(d.trim_end_matches('\\'))){(Lookup::Doi(d),"source_doi",serde_json::Value::Null)}else{let l=&a["citation_locator"];
  let c=match(l["journal"].as_str().and_then(ash_issn),l["volume"].as_str(),l["first_page"].as_str()){(Some(issn),Some(v),Some(p))=>Citation{issn:issn.into(),volume:v.into(),issue:l["issue"].as_str().map(String::from),first_page:p.into()},_=>return fail("no_identifier","the ASH link states neither a DOI nor a journal citation we can resolve".into())};
  match xw::doi_for_citation(f,&c).await{Ok((l,ev))=>(l,"source_citation",ev),Err(e)=>return fail("citation_unresolved",e)}};
 let sref=SourceRef{source_url:target.into(),evidence_url:Some(landing.into()),source_title:None,item_type:Some("guideline".into()),key_prefix:"ash-pmc".into(),id_route:route.into(),notes:vec![]};
 let mut extra=json!({"source_landing":landing,"role":"publisher_article_terminal","source_label":a["label"],"doi":a["doi"],"citation_locator":a["citation_locator"]});if !resolution.is_null(){extra["citation_resolution"]=resolution;}
 let mut c=cx.try_id(s,f,lookup,sref,extra,Some(source_doc)).await;let row=c.row.take();(row,c)}
fn issue(s:&SourceEntry,u:String,e:String)->PlanRow{PlanRow{source_id:s.id.clone(),doc_key:format!("ash-{}-unresolved",common::short_hash(&u)),url:u,title:None,rendition:None,version:None,extra:json!({"discovery_error":e})}}
#[async_trait::async_trait]impl Adapter for AshHematology{
 async fn discover(&self,s:&SourceEntry,f:&Fetcher,limit:Option<usize>)->Result<Vec<PlanRow>>{if limit==Some(0){return Ok(vec![])}let mut q=VecDeque::from([s.catalog_url.as_deref().unwrap_or(ROOT).to_string()]);let mut seen=HashSet::new();let mut out=vec![];let mut cx=xw::Session::default();while let Some(u)=q.pop_front(){if !seen.insert(u.to_lowercase()){continue}if seen.len()>500{out.push(issue(s,u,"ASH topic enumeration bound reached".into()));break}let p=match f.get_ok(&u).await{Ok(p)=>p,Err(e)=>{out.push(issue(s,u,format!("ASH source page unavailable: {e:#}")));if limit.is_some_and(|n|out.len()>=n){break}continue}};let b=Url::parse(&p.record.final_url)?;if b.host_str()!=Some("www.hematology.org"){out.push(issue(s,u,"ASH source page redirected outside publisher".into()));continue}let(title,body,children,assets)=match page(&p.text(),&b){Ok(x)=>x,Err(e)=>{out.push(issue(s,u,format!("ASH source template: {e:#}")));continue}};for child in children{q.push_back(child)}let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&assets))?.as_bytes());let landing=out.len();out.push(PlanRow{source_id:s.id.clone(),doc_key:format!("ash-{}-{}",common::short_hash(&u),&hash[..12]),url:u.clone(),title:Some(title),rendition:Some("html".into()),version:None,extra:json!({"snapshot":hash})});if limit.is_some_and(|n|out.len()>=n){return Ok(out)}
  for a in assets{if a["role"]!="publisher_article_terminal"{continue}let Some(target)=a["url"].as_str()else{continue};let mut row=issue(s,target.into(),String::new());row.extra["source_landing"]=json!(u);row.extra["role"]=json!("publisher_article_terminal");row.extra["oa_route"]=json!("pmc_crosswalk");row.extra["doi"]=a["doi"].clone();row.extra["citation_locator"]=a["citation_locator"].clone();row.extra["source_label"]=a["label"].clone();
   // Round 2: the article's open-access PMC copy (Blood Advances guidelines are CC BY-NC-ND in PMC); the publisher HTML is still not scraped.
   let source_doc=format!("guideline:{}:{}",s.id,out[landing].doc_key);let(open,c)=crosswalk(s,f,&mut cx,&a,target,&u,source_doc).await;xw::record_on(&mut out[landing],&c);
   match open{Some(r)=>out.push(r),None if c.status=="duplicate"=>{},None=>{row.extra["discovery_error"]=json!(format!("ASH guideline journal article, PMC crosswalk {}: {}; publisher HTML not scraped",c.status,c.reason.clone().unwrap_or_default()));xw::record_on(&mut row,&c);out.push(row)}}
   if limit.is_some_and(|n|out.len()>=n){return Ok(out)}}}Ok(out)}
 async fn extract(&self,s:&SourceEntry,f:&Fetcher,r:&PlanRow)->Result<GuidelineDoc>{if cw::is_crosswalk_row(r){return xw::extract(s,f,r).await}if let Some(e)=r.extra["discovery_error"].as_str(){bail!("{e}")};let p=f.get_ok(&r.url).await?;let b=Url::parse(&p.record.final_url)?;if b.host_str()!=Some("www.hematology.org"){bail!("ASH source redirected outside publisher")};let(title,body,children,assets)=page(&p.text(),&b)?;let hash=crate::common::sha256_hex(serde_json::to_string(&(&title,&body,&assets))?.as_bytes());if r.extra["snapshot"].as_str()!=Some(hash.as_str()){bail!("ASH source page changed; re-plan")};let(blocks,mut warnings)=blocks_from_html(&body,Some(&b),None);warnings.push("ASH topic page and implementation resources are not the full guideline article; journal access, evidence assets and rights require independent validation. Topic inventory is not fully reconciled.".into());Ok(GuidelineDoc{source_id:s.id.clone(),doc_key:r.doc_key.clone(),work_key:Some(format!("ash-{}",common::short_hash(&r.url))),title,url:r.url.clone(),item_type:Some(if children.is_empty()||assets.iter().any(|a|a["role"]=="publisher_article_terminal"){"guideline_topic_landing"}else{"topic_directory"}.into()),status:"unknown".into(),rights:Rights{status:"unknown".into(),note:Some("ASH source page and each journal, overview and teaching resource have independent rights.".into()),..Default::default()},blocks,relations:xw::relations_from_extra(&r.extra,&[]),attachments:assets,fetches:vec![p.record],warnings,..Default::default()})}
}
#[cfg(all(test, feature = "guideline-fixtures"))]mod tests{use super::*;const CAT:&str=include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/research-1.html"));const SURG:&str=concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/research-2.part-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/research-2.part-2.html")));const URL:&str="https://www.hematology.org/resources/clinical-practice-guidelines/venous-thromboembolism-guidelines/prevention-in-hospitalized-surgical-patients";
#[test]fn source_catalog_and_surgical_roles(){let(_,_,children,_)=page(CAT,&Url::parse(ROOT).unwrap()).unwrap();assert!(children.iter().any(|x|x.to_lowercase().ends_with("/venous-thromboembolism-guidelines")));let(t,body,_,a)=page(SURG,&Url::parse(URL).unwrap()).unwrap();assert!(t.contains("Prevention in Hospitalized Surgical Patients"));assert!(body.contains("reviewed annually"));assert!(a.iter().any(|x|x["role"]=="publisher_article_terminal"&&x["url"].as_str().unwrap().contains("/3/23/3898/429211")));assert!(a.iter().any(|x|x["role"]=="guideline_overview"&&x["label"]=="Full VTE guidelines"));assert!(a.iter().any(|x|x["role"]=="teaching_slides"));}
#[tokio::test]async fn surgical_page_is_not_journal_and_terminal_error_is_separate(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(URL,SURG.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"ash_hematology","access":"public","enabled":true,"catalog_url":URL})).unwrap();let rows=AshHematology.discover(&s,&f,Some(2)).await.unwrap();assert_eq!(rows.len(),2);let d=AshHematology.extract(&s,&f,&rows[0]).await.unwrap();assert_eq!(d.item_type.as_deref(),Some("guideline_topic_landing"));assert!(d.attachments.iter().any(|x|x["role"]=="publisher_article_terminal"));assert!(rows[1].extra["discovery_error"].is_string());assert!(d.warnings.iter().any(|s|s.contains("not the full guideline article")));}
}

#[cfg(all(test, feature = "guideline-fixtures"))]mod source_graph_round_ad{use super::*;const HUB:&str=concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/vte-hub.part-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/vte-hub.part-2.html")));const SURG:&str=concat!(include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/research-2.part-1.html")),include_str!(concat!(env!("CARGO_MANIFEST_DIR"),"/tests/fixtures/guidelines/ash_hematology/research-2.part-2.html")));const HUB_URL:&str="https://www.hematology.org/resources/clinical-practice-guidelines/venous-thromboembolism-guidelines";
#[test]fn hub_quicklinks_deduplicate_and_find_surgical(){let(_,_,links,_)=page(HUB,&Url::parse(HUB_URL).unwrap()).unwrap();assert!(links.len()>=10);let mut seen=std::collections::HashSet::new();assert!(links.iter().all(|u|seen.insert(u.to_lowercase())));assert!(links.iter().any(|u|u.to_lowercase().ends_with("/prevention-in-hospitalized-surgical-patients")));}
#[tokio::test]async fn source_hub_reaches_actual_surgical_child(){let t=tempfile::tempdir().unwrap();let f=Fetcher::new(t.path(),true,500,1<<20,"").unwrap();f.seed_cache_for_tests(HUB_URL,HUB.as_bytes(),"text/html");let(_,_,links,_)=page(HUB,&Url::parse(HUB_URL).unwrap()).unwrap();let child=links.iter().find(|u|u.to_lowercase().ends_with("/prevention-in-hospitalized-surgical-patients")).unwrap();f.seed_cache_for_tests(child,SURG.as_bytes(),"text/html");let s:SourceEntry=serde_json::from_value(json!({"id":"ash_hematology","access":"public","enabled":true,"catalog_url":HUB_URL})).unwrap();let rows=AshHematology.discover(&s,&f,Some(30)).await.unwrap();let row=rows.iter().find(|r|r.url==*child&&r.extra["snapshot"].is_string()).unwrap();let d=AshHematology.extract(&s,&f,row).await.unwrap();assert!(d.title.contains("Prevention in Hospitalized Surgical Patients"));assert!(d.attachments.iter().any(|a|a["role"]=="publisher_article_terminal"));}
}

